    [5] = {
      id = 92381,
      step = 5,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=（抱拳行礼，笑声洪亮）哈哈哈！这方宝地烟火气十足，是个好灶头！您就是主厨吧？我是红烧狮子头，今日特来拜会！",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [6] = {
      id = 92381,
      step = 6,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=2=欢迎，红烧狮子头。早就听闻你的大名了。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [7] = {
      id = 92381,
      step = 7,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=主厨客气了！我走南闯北，就爱个热闹。往后若有需要帮衬、调解的事儿，尽管吩咐！我这人没别的，就是重个“义”字。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [8] = {
      id = 92381,
      step = 8,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=2=听你这么说，感觉料理次元的安定又多了一分保障。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [9] = {
      id = 92381,
      step = 9,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=（爽朗一笑）分内之事！来，这碗热汤您趁热喝，算是我的一点见面礼，暖暖身子！",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    }
  },
