    },
    [6] = {
      id = 92382,
      step = 6,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=（坐在石凳上，神色温和）江湖路远，互相照应是应该的。看着大家能开开心心的，我这心里头就踏实。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [7] = {
      id = 92382,
      step = 7,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=2=有你在，确实让人安心不少。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [8] = {
      id = 92382,
      step = 8,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=（微微感慨）实不相瞒，也是年轻时跌过跤，受过旁人恩惠，才更知雪中送炭的可贵。如今有能力了，自然想为这“大家庭”多出份力。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [9] = {
      id = 92382,
      step = 9,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=2=这份心意，很难得。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [10] = {
      id = 92382,
      step = 10,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=（正色道）主厨您才是，琐事繁杂。若有我能分担的，请一定直言。我愿做您最坚实的后盾。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    }
