    [5] = {
      id = 92383,
      step = 5,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=主厨，请品鉴这道“四喜团圆狮子头”！我今日可是用了十二分的心意。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [6] = {
      id = 92383,
      step = 6,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=2=香气醇厚，形态饱满，光是看着就觉得很圆满。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [7] = {
      id = 92383,
      step = 7,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=（眼中含笑）不错。这道菜的精髓就在于“团圆”二字。用料虽寻常，贵在火候恰到好处，让滋味充分融合。正如我们次元小屋，大家和而不同，却能聚在一起，共创美味，这便是最好的“江湖”。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [8] = {
      id = 92383,
      step = 8,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=对我而言，这里就是我心安之处，是值得我守护的“新江湖”。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [9] = {
      id = 92383,
      step = 9,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=2=能得你如此看待，是次元小屋的荣幸。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [10] = {
      id = 92383,
      step = 10,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=您言重了。来，快尝尝看，这便是我心中的“家”的味道。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    }
  },
