      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=主厨，这枚戒指……您的意思是？（语气庄重，略带询问）",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [6] = {
      id = 92384,
      step = 6,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=2=我希望未来能与你同行，共同守护这个家。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [7] = {
      id = 92384,
      step = 7,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=（深吸一口气，目光坚定而温暖）我红烧狮子头半生漂泊，自认侠肝义胆，不畏风雨。但您这份信任与托付，却让我感到前所未有的重任与……温暖。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [8] = {
      id = 92384,
      step = 8,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=此物我收下了。它不是羁绊，而是誓约。从今往后，您的理想即为我的方向，您欲守护的，便是我刀山火海也要维护的。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [9] = {
      id = 92384,
      step = 9,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=（郑重行礼）主公，前路漫漫，我愿与您同心协力，共铸盛世！这江湖，我们一起去闯！",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [10] = {
      id = 92384,
      step = 10,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=不过在此之前，先让我确保您吃饱吃好，这可是头等大事。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    }
  },
