      delay = 0
    },
    [11] = {
      id = 94351,
      step = 11,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=嚯，就跟我以前在曲艺团学员班似的，逮到一个老先生那就是玩命的学呀。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [12] = {
      id = 94351,
      step = 12,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=您老也别上火，这十八街麻花儿怎么去做，我马上一五一十教给您。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [13] = {
      id = 94351,
      step = 13,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=得嘞，您入座。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [14] = {
      id = 94351,
      step = 14,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=这事儿啊，还得从清朝末年说起。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [15] = {
      id = 94351,
      step = 15,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=诶，这天津卫海河西头的十八街，有个麻花铺子。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [16] = {
      id = 94351,
      step = 16,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=他们家介个麻花啊，十里八里，嗬，有名的很。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [17] = {
      id = 94351,
      step = 17,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=只是到了后来啊，这大家的新鲜劲儿可就过了。一直都是这个味儿，换了谁也腻歪啊。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [18] = {
      id = 94351,
      step = 18,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=这掌柜的是急得直嘬牙花子，寻思这可咋办啊，老祖宗的招牌眼看着砸手上了。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [19] = {
      id = 94351,
      step = 19,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=诶，这眉头皱的啊，一脸都是褶子，跟个包子似的。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [20] = {
      id = 94351,
      step = 20,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=咋办呢？不知道咋办。急三火四的。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [21] = {
      id = 94351,
      step = 21,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=您猜后来怎么着？有一天这店里的少东家，夜里回来晚了。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [22] = {
      id = 94351,
      step = 22,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=这大晚上的回来肚里饿呀，就想找点点心吃。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [23] = {
      id = 94351,
      step = 23,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=结果啊，这点心盒子都见了底了，嘛都不剩，就剩点渣。咋办呢。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [24] = {
      id = 94351,
      step = 24,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=少东家就把这些点心渣，和在麻花面里炸。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [25] = {
      id = 94351,
      step = 25,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=结果这一出来啊，香气扑鼻！嘿，这新的麻花儿不就出来了嘛。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [26] = {
      id = 94351,
      step = 26,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=嘿，从今往后，十八街的麻花铺多了一种麻花。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [27] = {
      id = 94351,
      step = 27,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=麻花的白条和麻条之间夹进了什锦酥馅。桂花、闽姜、核桃仁、花生、芝麻，还有青红丝和冰糖",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [28] = {
      id = 94351,
      step = 28,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=这家伙，门庭若市啊，慢慢的就出了名儿咯。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [29] = {
