      step = 29,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=最后这家店也火了，这麻花也火了，这就是十八街麻花的故事咯。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [30] = {
