      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=直到法国路易十六时期，鹅肝被进贡至宫廷献给路易十五，在品尝之后，深受国王喜爱，从此声名大噪。",
      offset = 0,
