      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=当时许多知名作家、音乐家及艺术家都有所称赞，自此奠定了高贵珍馐的不凡地位。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [19] = {
      id = 93341,
      step = 19,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=在1870年，鹅肝第一次被烹食。一名点心师在Mar6A.chal de Contades 的服务中，鹅肝被包在面团里，并在招待会上使用。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [20] = {
      id = 93341,
      step = 20,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=从那个时候起，史特拉斯堡就和鹅肝联系在了一起，并且许多人认为史特拉斯堡的鹅肝在世界上是最好的。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [21] = {
      id = 93341,
      step = 21,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=不过嘛，虽然名称是“鹅肝”，但实际上今天大部分的法国鹅肝是鸭肝制成的。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [22] = {
      id = 93341,
      step = 22,
      background = 0,
      music = 0,
      bgColor = "",
      sound = 0,
      type = 2,
      content = "1=1=由鸭肝制成的法国鹅肝味道浓郁，而用鹅肝制成的法国鹅肝则肉质细腻。没尝鹅肝，不能算是真正吃过法国菜。",
      offset = 0,
      shake = 0,
      scale = 0,
      delay = 0
    },
    [23] = {
